import { ApiProperty } from '@nestjs/swagger';
import { IsISO8601, IsNumber, IsUUID, Max, Min } from 'class-validator';

/** Guards the column against absurd values; the configured limit (50 m) answers LOCATION_INACCURATE. */
const ACCURACY_INPUT_MAX_M = 100_000;

export class CreateCheckInDto {
  @ApiProperty({
    format: 'uuid',
    description:
      'Generated by the app once per check-in; a retry with the same id returns the stored result (200).',
  })
  @IsUUID()
  clientId: string;

  @ApiProperty({ format: 'uuid' })
  @IsUUID()
  placeId: string;

  @ApiProperty({ minimum: -90, maximum: 90 })
  @IsNumber()
  @Min(-90)
  @Max(90)
  lat: number;

  @ApiProperty({ minimum: -180, maximum: 180 })
  @IsNumber()
  @Min(-180)
  @Max(180)
  lng: number;

  @ApiProperty({
    minimum: 0,
    maximum: ACCURACY_INPUT_MAX_M,
    description: 'Above the configured maximum (50 m) → LOCATION_INACCURATE.',
  })
  @IsNumber()
  @Min(0)
  @Max(ACCURACY_INPUT_MAX_M)
  accuracyM: number;

  @ApiProperty({
    format: 'date-time',
    description:
      'When the fix was taken: at most 2 min ahead of the server (400) and at most 72 h old (CHECK_IN_TOO_OLD).',
  })
  @IsISO8601({ strict: true })
  recordedAt: string;
}
